const m="Loading screen",f=[{id:"loadingEdge",pr:1194,group:"Loading screen",label:"Edge first",note:"How strongly the stars light from the edge in (loading.edge; 1 as built, 0 plain random). Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:0,max:3,step:.1},default:1,persist:!0,apply:{knob:"loading.edge"}},{id:"loadingRate",pr:1194,group:"Loading screen",label:"Stars a second",note:"At most this many stars light a second, so a jump in the load fills over a moment (loading.rate; 90 as built). Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:10,max:300,step:10},default:90,persist:!0,apply:{knob:"loading.rate"}},{id:"loadingFlash",pr:1194,group:"Loading screen",label:"Flash",note:"How long each star flashes as it lights, seconds (loading.flash; 0.6 as built). Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:0,max:2,step:.05},default:.6,persist:!0,apply:{knob:"loading.flash"}},{id:"loadingGhost",pr:1194,group:"Loading screen",label:"Unlit stars",note:"How bright the stars not yet lit show (loading.ghost; 0 as built: an empty sky, Ed's call, 2026-10-26). Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:0,max:1,step:.02},default:0,persist:!0,apply:{knob:"loading.ghost"}},{id:"loadingNova",pr:1194,group:"Loading screen",label:"Supernova",note:"The heart's star going supernova to white, seconds (loading.nova; 2.6 as built). Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:.5,max:6,step:.1},default:2.6,persist:!0,apply:{knob:"loading.nova"}},{id:"loadingClear",pr:1194,group:"Loading screen",label:"White clearing",note:"The white clearing into the bedroom, seconds (loading.clear; 1.2 as built). Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:.2,max:4,step:.1},default:1.2,persist:!0,apply:{knob:"loading.clear"}},{id:"loadingFps",pr:1194,group:"Loading screen",label:"Frames a second",note:"How often the screen draws while the game loads (loading.fps; 10 as built): each frame costs the load a little (at 20 its cold load in the cloud came 5.4 s later). About 20 once it's ready, for the supernova. Remembered on this browser; takes effect on the next load (the screen is over before the game can pause).",control:{type:"slider",min:2,max:30,step:1},default:10,persist:!0,apply:{knob:"loading.fps"}}],b={pr:1194,group:m,decisions:f},y=1127,w="Tree height cap",k=[{id:"treeCapKeep",pr:1127,group:"Tree height cap",label:"Tree cap: keep above it",note:`How much of each tree's height over the cap it keeps (Ed, 2026-10-26: "Can we have the tree height cap as a menu slider?"): 1 since Ed, 2026-10-26 ("Tall trees look awesome"): no cap at all, every tree at its art's own height; 0.35 as built before (a 45 m tree showed 29 m) (the art's own heights: home's trees average 23.7 m, not 19.3). The oak's crown tops out at 32.3 m: with the cap from 20 m, anything over 0.35 has home trees taller than it (0.4: 675 of its 17,069; 0.6: 2,108; 1: 4,107). The jungle's tallest grow most (49 m to about 67 m at 0.6). Live: no rebake, drawn again at once.`,control:{type:"slider",min:0,max:1,step:.05},default:1,apply:{knob:"treeCap.keep"}},{id:"treeCapFrom",pr:1127,group:"Tree height cap",label:"Tree cap: from (m)",note:"The height (metres) over which a tree is squeezed: 20 as built, so her 24 m treetop flight stays mostly over the canopy. Raising it lets more trees stand at their full height, and they top the oak's 32.3 m crown sooner (25 m at keep 0.35: 986 of home's trees). Live: no rebake, drawn again at once.",control:{type:"slider",min:10,max:40,step:1},default:20,apply:{knob:"treeCap.from"}}],v={pr:y,group:w,decisions:k},_=1149,x="Area blend",$=[{id:"areaBlend",pr:1149,group:"Area blend",label:"Area blend (m)",note:`How far each area's trees, bushes and ground cover reach into its neighbours (Ed, 2026-10-26: "The effect that makes tree placement from neighbouring areas blend should be increased"): the neighbour's share ramps from about half at the border to none this many metres in, the band wandering by the tuning's areaEdgeBlend.warp. 40 was the old blend, 0 a hard edge. A new map: it reloads.`,control:{type:"slider",min:0,max:160,step:10},default:80,apply:{knob:"areaEdgeBlend.width",reload:!0}}],S={pr:_,group:x,decisions:$},T=1162,H="Telescope look",C=[{id:"telescopeHazeNear",pr:1162,group:"Telescope look",label:"Haze starts (m)",note:"Through the telescope: where its haze starts to fade the land toward one colour (it looks out from about 260 m).",control:{type:"slider",min:0,max:2e3,step:10},default:320,apply:{knob:"telescope.hazeNear"}},{id:"telescopeHazeFar",pr:1162,group:"Telescope look",label:"Haze full (m)",note:"Through the telescope: where its haze is full, the land all haze colour. Further keeps more colour far off.",control:{type:"slider",min:200,max:4e3,step:20},default:1e3,apply:{knob:"telescope.hazeFar"}},{id:"telescopeVignette",pr:1162,group:"Telescope look",label:"Vignette",note:"How dark the telescope view's edges are (0 none).",control:{type:"slider",min:0,max:1,step:.05},default:.6,apply:{knob:"telescope.vignette"}}],L={pr:T,group:H,decisions:C},j=1176,E="Places kept clear",O=[{id:"revealRunestone",pr:1176,group:"Places kept clear",label:"Clear in front of runestones",note:`Ed, 2026-10-26: "we might want this for other important points of interest, such as runestone areas, finds, flasks". On: within reveal.runestone.radius metres of an area's runestone, on the ground, the trees and scenery in front of the stone and its fight's open middle fade away (render/view/reveal.ts), as they do in a legend's circle. On since Ed, 2026-10-26 ("All four on"); off to compare.`,control:{type:"toggle"},default:!0,apply:{knob:"reveal.runestone.on"}},{id:"revealRunestoneRadius",pr:1176,group:"Places kept clear",label:"Runestone clear area (m)",note:`How far round a runestone the scenery in front of it fades (Ed, 2026-10-26: "the fading area around a runestone is relatively small (say a 30m radius)"): only while she's within this many metres of the stone, and only what stands within it, so the woods round a fight don't thin out beyond. Live.`,control:{type:"slider",min:10,max:60,step:5},default:30,apply:{knob:"reveal.runestone.radius"}},{id:"revealFind",pr:1176,group:"Places kept clear",label:"Clear in front of the find",note:`On: near tonight's trunk or wreck (within reveal.find.radius metres, until it's taken), the scenery in front of it fades away. On since Ed, 2026-10-26 ("All four on"); off to compare.`,control:{type:"toggle"},default:!0,apply:{knob:"reveal.find.on"}},{id:"revealFlask",pr:1176,group:"Places kept clear",label:"Clear in front of flasks",note:'On: near a relic flask lying in the woods (within reveal.flask.radius metres), the scenery in front of it fades away. On since Ed, 2026-10-26 ("All four on"); off to compare.',control:{type:"toggle"},default:!0,apply:{knob:"reveal.flask.on"}}],A={pr:j,group:E,decisions:O},R=1177,M="Pointer pins",D=[{id:"pinGap",pr:1177,group:"Pointer pins",label:"Pins: float above (px)",note:`How far the pointers' arrow tips float over what they point at, in screen pixels (Ed, 2026-10-26: "pins should be a bit higher"): 20 as built (the first build had 6; 12 still nearly touched a hat). Every pin: her hats, the stones, the Dowsing hat's flask, the wave pointer over the pulse and the house's pins. Live.`,control:{type:"slider",min:0,max:40,step:1},default:20,apply:{knob:"pins.gap"}}],F={pr:R,group:M,decisions:D},B=1182,z="House music",I=[{id:"houseMusicMuffle",pr:1182,group:"House music",label:"Muffle (Hz)",note:"In the treehouse the music slows and muffles: its low-pass closes to this as the house's world slows. Lower is more muffled (a legend's circle is 320). Only the music; other sounds as they are.",control:{type:"slider",min:150,max:4e3,step:10},default:800,apply:{knob:"music.house.muffle"}}],P={pr:B,group:z,decisions:I},G=1227,N="Hidden witch",q=[{id:"occSilhouette",pr:1227,group:"Hidden witch",label:"Silhouette",note:"Where scenery still hides her, her shape drawn flat in her glow colour through it, at this strength: 0.55 as built, 0 none (she's simply hidden), 1 a solid glow-coloured cut-out. Live.",control:{type:"slider",min:0,max:1,step:.05},default:.55,apply:{knob:"occlusion.silhouette"}},{id:"occSeeThrough",pr:1227,group:"Hidden witch",label:"See-through",note:"How clear the soft circle round her is at its middle, where tall things in front of her fade: 0 as built (fully see-through there), 1 not at all (solid: no circle, the silhouette alone shows her). Live.",control:{type:"slider",min:0,max:1,step:.05},default:0,apply:{knob:"occlusion.fadeOpacity"}},{id:"occEdge",pr:1227,group:"Hidden witch",label:"Soft edge",note:"Where the circle eases back to solid, as a share of its radius past her body: 3 as built; lower, a smaller, harder-edged hole; higher, a wider, softer one. Live.",control:{type:"slider",min:0,max:8,step:.25},default:3,apply:{knob:"occlusion.edge"}},{id:"occMinHeight",pr:1227,group:"Hidden witch",label:"Fade things taller than (m)",note:"Only things taller than this (metres) standing in front of her fade round her: 2.5 as built, so bushes and props stay solid and trees, rocks and ruins fade; 0, everything in front of her fades. Live.",control:{type:"slider",min:0,max:10,step:.5},default:2.5,apply:{knob:"occlusion.minHeight"}},{id:"glowHue",pr:1227,group:"Hidden witch",label:"Glow colour (hue)",note:"Her own glow's colour round the colour wheel (light.spooky.glowHue, the spooky mood's; render/lighting.ts uGlowRgb): 0.08 as built, a warm amber-orange; 0 red, 0.17 yellow, 0.33 green, 0.5 cyan, 0.67 blue, 0.83 magenta. Her pool on the ground, its light on what's near her and her silhouette all take it; the swatch is the colour. Live.",control:{type:"slider",min:0,max:1,step:.01,swatch:{hue:"light.spooky.glowHue",sat:"light.spooky.glowSat"}},default:.08,apply:{knob:"light.spooky.glowHue"}},{id:"glowSat",pr:1227,group:"Hidden witch",label:"Glow colour (saturation)",note:"How coloured her glow is (light.spooky.glowSat): 0.55 as built; 0 white light, 1 the hue at its deepest. Live.",control:{type:"slider",min:0,max:1,step:.05,swatch:{hue:"light.spooky.glowHue",sat:"light.spooky.glowSat"}},default:.55,apply:{knob:"light.spooky.glowSat"}},{id:"glowPower",pr:1227,group:"Hidden witch",label:"Glow strength",note:"Her own glow at its brightest (glowPower): 0.95 as built; 0 no glow (her silhouette keeps its colour); over 1 the bright middle of her pool spreads wider, as the light is capped at full. Live.",control:{type:"slider",min:0,max:2,step:.05},default:.95,apply:{knob:"glowPower"}}],W={pr:G,group:N,decisions:q},V=1233,J="Oak crown",U=[{id:"crownWhole",pr:1233,group:"Oak crown",label:"Crown whole over the Terrace",note:`On, the great oak's crown is whole over the Terrace as over every room: no gap over it, no notch out to the crown's edge and no ring of lights round them (Ed, 2026-10-26: "I'd like to try the treehouse canopy not being cut-through while she's in treehouse mode - this will make it easier for her to land in the treehouse successfully, as the area is bigger"). Indoors it's cleared over the room she's in and round her, the Terrace too, as ever. Off: the gap and its notch as before (#1172). The crown's grown again as it's flipped.`,control:{type:"toggle"},default:!0,apply:{knob:"treehouse.house.crown.whole"}},{id:"terraceRoom",pr:1233,group:"Oak crown",label:"Terrace drawn as one of the rooms",note:`On, the Terrace is one of the house's rooms under the crown, not drawn on its own (Ed, 2026-10-26: "I also want to try not having the terrace drawn separately"): from outside its art (its round of wood, her decks, the DJ table, the tempo over them) isn't drawn, only the crown over it, and it shows when she's in the house as every room does (a knockout's candles still show). In the house it's as before, the forest showing behind it. Off: the Terrace drawn on its own from outside, as before (#1172).`,control:{type:"toggle"},default:!0,apply:{knob:"treehouse.house.terraceRoom"}},{id:"forestReveal",pr:1233,group:"Oak crown",label:"Forest fades in behind the house (s)",note:'In the house the forest stays dark behind every room, the Terrace too, till the island has loaded (its art drawn); then it fades in behind the whole treehouse over this many seconds of her clock, and stays (Ed, 2026-10-26: "When the forest has loaded, fade it in gradually behind the whole treehouse"). It was dark behind the enclosed rooms always. 20 (Ed, 2026-10-26: "Fade in time: 20 seconds"); 0.5 nearly at once.',control:{type:"slider",min:.5,max:40,step:.5},default:20,apply:{knob:"treehouse.house.dark.reveal"}}],K={pr:V,group:J,decisions:U},Q=1303,Y="Creature momentum",X=[{id:"momentumOn",pr:1303,group:"Creature momentum",label:"Creature momentum",note:`Creatures chasing her turn no faster than their limit, react to where she was a moment ago and lead her only with telegraphed attacks (Ed, 2026-10-27: "less worth dodging because animals can turn towards her instantly"). Off: as before. Each species' own numbers are its class's (heavy, normal, light) or its folder's; these sliders scale them all.`,control:{type:"toggle"},default:!0,apply:{knob:"creatureMomentum.on"}},{id:"momentumStrikes",pr:1303,group:"Creature momentum",label:"Momentum in strikes",note:`Off as built: momentum shapes the chase, a pack's approach and its lull; telegraphed run-ins (a wind-up's surge in, a pack's tell and combo) track her as before, so a lunge that starts still reaches her (Ed's v3893). On: those have momentum too (creatureMomentum.strikes), the stronger answer to "they turn towards her instantly", most of their run-in being their wind-up; lunges then fall short more often.`,control:{type:"toggle"},default:!1,apply:{knob:"creatureMomentum.strikes"}},{id:"momentumTurn",pr:1303,group:"Creature momentum",label:"Turn rate ×",note:"Times every species' turn limit (creatureMomentum.turn; 1 as built: heavy 220°/s, normal 420, light 650, falling as turn / (1 + speed / k)). Lower: wider arcs, more overshoot on a sidestep; higher: they cut back sooner.",control:{type:"slider",min:.2,max:4,step:.05},default:1,apply:{knob:"creatureMomentum.turn"}},{id:"momentumDelay",pr:1303,group:"Creature momentum",label:"Reaction delay ×",note:"Times every species' reaction delay (creatureMomentum.delay; 1 as built: heavy 0.4 s, normal 0.25, light 0.15): it chases where she was that long ago, so a sidestep or blink fools it for that long. 0: it sees her at once.",control:{type:"slider",min:0,max:3,step:.05},default:1,apply:{knob:"creatureMomentum.delay"}},{id:"momentumChaseLead",pr:1303,group:"Creature momentum",label:"Chase lead +s",note:"Seconds of her velocity every species leads her by when just chasing, added to its own (creatureMomentum.chaseLead; 0 as built: no prediction, only the wolf leads a little, 0.15 s). Ed: prediction mostly for telegraphed attacks.",control:{type:"slider",min:0,max:1,step:.05},default:0,apply:{knob:"creatureMomentum.chaseLead"}},{id:"momentumStrikeLead",pr:1303,group:"Creature momentum",label:"Telegraphed lead ×",note:"Times the lead telegraphed attacks take on her (creatureMomentum.strikeLead; 1 as built, as they were): a melee wind-up's tracking, a charge's lane, a leap, a swoop's dive, shots and lobs. 0: they aim where she is.",control:{type:"slider",min:0,max:2,step:.05},default:1,apply:{knob:"creatureMomentum.strikeLead"}}],Z={pr:Q,group:Y,decisions:X},ee=227,oe="Decisions panel",te=[{id:"style",pr:227,group:"Decisions panel",label:"Pixel style",note:"How every sprite is baked: bold (3 hue-shifted tones, a selective outline) or ref (one tone family, a near-black outline).",control:{type:"choice",options:[{value:"bold",label:"Bold"},{value:"ref",label:"Ref"}]},default:"bold",apply:{param:"style",reload:!0}},{id:"growth",pr:227,group:"Decisions panel",label:"Wild growth a wave",note:"Creatures each wild area gains every wave (0.5: one every other wave).",control:{type:"slider",min:.25,max:1,step:.25},default:.5,apply:{knob:"population.growth.perWave"}},{id:"grace",pr:227,group:"Decisions panel",label:"Grace after a hit (s)",note:"Seconds after the witch is hit in which no other blow lands, so a pack striking together costs one hit.",control:{type:"slider",min:0,max:1,step:.05},default:.5,apply:{knob:"witchHealth.grace"}},{id:"legendFlash",pr:227,group:"Decisions panel",label:"Legend hit flash",note:"How big and long a legend's blow flashes (0: like anyone's, 0.5: twice, 1: three times).",control:{type:"slider",min:0,max:1,step:.05},default:.5,apply:{knob:"attackFx.legendFlash"}}],se={pr:ee,group:oe,decisions:te},ae=243,ne="Charges and leaps go further",re=[{id:"chargeReach",pr:243,group:"Charges and leaps go further",label:"Charge length",note:"How far charges run (their time and overshoot past her), times each species' own: 1 as before round 13, 2 now.",control:{type:"slider",min:1,max:3,step:.25},default:2,apply:{knob:"fight.charge.reach"}},{id:"chargeTurn",pr:243,group:"Charges and leaps go further",label:"Charge turning",note:"How fast a charger turns as it brakes, times each species' own: lower is wider arcs (1 as before, 0.4 now).",control:{type:"slider",min:.2,max:1,step:.1},default:.4,apply:{knob:"fight.charge.turn"}},{id:"chargeBrake",pr:243,group:"Charges and leaps go further",label:"Charge momentum",note:"How hard a charger brakes after its run, times each species' own: lower carries more momentum (1 as before, 0.5 now).",control:{type:"slider",min:.2,max:1,step:.1},default:.5,apply:{knob:"fight.charge.brake"}},{id:"chargeContact",pr:243,group:"Charges and leaps go further",label:"Charges hurt on touch",note:"A charging creature hurts every foe it touches on the way (once each), not only its target as it reaches it.",control:{type:"toggle"},default:!0,apply:{knob:"fight.charge.contact"}},{id:"leapReach",pr:243,group:"Charges and leaps go further",label:"Leap length",note:"How far off a creature leaps from, times its own (1 as before, 1.5 now); pounces land through metres past her.",control:{type:"slider",min:1,max:2.5,step:.25},default:1.5,apply:{knob:"fight.leap.reach"}},{id:"leapThrough",pr:243,group:"Charges and leaps go further",label:"Pounce carry-through (m)",note:"Metres past her a pounce lands (the lynx's); less than 0, short of her (-1.5 before round 13).",control:{type:"slider",min:-1.5,max:10,step:.5},default:5,apply:{knob:"fight.leap.through"}},{id:"daze",pr:243,group:"Charges and leaps go further",label:"Downed stun (s)",note:"Seconds a wild creature knocked down in a fight lies stunned (she can still invite it) before it runs off home (8 before round 13; Ed: 20).",control:{type:"slider",min:4,max:30,step:1},default:20,apply:{knob:"combat.daze"}},{id:"pursue",pr:243,group:"Charges and leaps go further",label:"Chase past their area (m)",note:"How far past its area's edge a wild animal chases her (or her party) before it gives up and retreats home (10 before round 13; Ed: 30).",control:{type:"slider",min:0,max:80,step:5},default:30,apply:{knob:"combat.leaveArea"}}],ie={pr:ae,group:ne,decisions:re},le=249,de="Stars through the tilt-shift",pe=[{id:"skyBlur",pr:249,group:"Stars through the tilt-shift",label:"Stars through the blur",note:"How much of the tilt-shift blur the night sky takes: 0 leaves the stars sharp, 1 blurs them like the ground.",control:{type:"slider",min:0,max:1,step:.05},default:.3,apply:{knob:"tiltShift.skyBlur"}},{id:"tiltTreetop",pr:249,group:"Stars through the tilt-shift",label:"Tilt-shift from the treetops",note:"The blur toward the top and bottom of the screen over the treetops (the ground's is 1.5).",control:{type:"slider",min:0,max:8,step:.5},default:3,apply:{knob:"tiltShift.treetop.strength"}}],he={pr:le,group:de,decisions:pe},ce=259,ue="Legends in half the areas",ge=[{id:"legendShare",pr:259,group:"Legends in half the areas",label:"Areas with a legend",note:"The share of areas (home never) with a sleeping legend, seeded and spread out; the rest have none (no clearing, quest or legend music). A new map: it reloads.",control:{type:"slider",min:.1,max:1,step:.05},default:.2,apply:{knob:"legends.share",reload:!0}}],me={pr:ce,group:ue,decisions:ge},fe=290,be="Legend layers",ye=[{id:"bombard",pr:290,group:"Legend layers",label:"Legend bombardment",note:"Damage an angry legend's lob or beam does a soundsystem (of 4000) when she's out of its reach (0: none). It always goes for her first.",control:{type:"slider",min:0,max:1e3,step:50},default:150,apply:{knob:"legends.bombard.damage"}},{id:"stomp",pr:290,group:"Legend layers",label:"Legend stomp",note:"A legend turning angry stamps on its own area's soundsystem at once (Ed's 'perhaps'): it only bites if you empty a partying area of the legend's kind.",control:{type:"toggle"},default:!1,apply:{knob:"legends.stomp.on"}},{id:"stompAngryAfter",pr:290,group:"Legend layers",label:"Restless time with the stomp (s)",note:"With the stomp on: seconds a legend with none of its kind about stays restless before it angers (the time to bring one back).",control:{type:"slider",min:60,max:240,step:15},default:120,apply:{knob:"legends.stomp.angryAfter"}},{id:"buffPower",pr:290,group:"Legend layers",label:"Legend buff strength",note:"How strong every legend's buff is, from quests and relics (1: as written, 2: twice the effect, a Fan two fans).",control:{type:"slider",min:1,max:4,step:.25},default:1,apply:{knob:"legends.buffPower"}},{id:"happyRange",pr:290,group:"Legend layers",label:"Happy legend reach (m)",note:"How far a happy legend (a relic's ally) reaches from its lair to hit the enraged: about 2 areas at 420.",control:{type:"slider",min:420,max:1500,step:60},default:420,apply:{knob:"legends.happyRange"}}],we={pr:fe,group:be,decisions:ye},ke=339,ve="No walking away",_e=[{id:"chargeChase",pr:339,group:"No walking away",label:"Charge speed vs her walk",note:"Charges run at least this many times her walking speed, on till they catch her walking straight away: only stepping out of the lane, a blink sideways or the treetops get her clear (0: as before).",control:{type:"slider",min:0,max:2.5,step:.1},default:1.6,apply:{knob:"fight.charge.chase"}},{id:"chargeMiss",pr:339,group:"No walking away",label:"Winded after a missed charge (s)",note:"Seconds a charger stands winded after a charge that hit nothing (dodged by a blink or a sidestep): the time to land your 💌s.",control:{type:"slider",min:0,max:3,step:.1},default:1.2,apply:{knob:"fight.charge.miss"}},{id:"leapLead",pr:339,group:"No walking away",label:"Leaps lead her",note:"How far a leap aims ahead of her, to where she'll be when it lands (1: all the way, 0: where she was).",control:{type:"slider",min:0,max:1,step:.1},default:1,apply:{knob:"fight.leap.lead"}}],xe={pr:ke,group:ve,decisions:_e},$e=346,Se="Balance pass 1",Te=[{id:"questCap",pr:346,group:"Balance pass 1",label:"Farthest dream (areas)",note:"A sleeping legend dreams of any other kind on the map, near or far, but none whose nearest area lies more than this many areas away (6 cuts about the farthest tenth on the ~96-area map, as 5 did on the old ~196; 0: no cap).",control:{type:"slider",min:0,max:10,step:.5},default:6,apply:{knob:"legends.questCap",reload:!0}}],He={pr:$e,group:Se,decisions:Te},Ce=483,Le="Quests point later",je=[{id:"questRoll",pr:483,group:"Quests point later",label:"Quest buff strength",note:"Every done quest's buff, this many times as strong as written, however far its dream creature lived (the encounter is the gamble, not the reward). A relic's stays as written.",control:{type:"slider",min:1,max:2,step:.05},default:1.25,apply:{knob:"legends.questRoll",reload:!0}},{id:"questLater",pr:483,group:"Quests point later",label:"Dreams from later areas",note:"On: a legend dreams of a kind living in an area later on the route than its own (deeper in). Off: any kind on the map, as before.",control:{type:"toggle"},default:!0,apply:{knob:"legends.questLater",reload:!0}}],Ee={pr:Ce,group:Le,decisions:je},Oe=726,Ae="Dream bubbles grow",Re=[{id:"bubbleScale",pr:726,group:"Dream bubbles grow",label:"Bubble size",note:"Every speech and dream bubble's pixel, the witch's and the creatures' (times each one's level share below).",control:{type:"slider",min:.5,max:2,step:.05},default:1,apply:{knob:"bubbles.scale"}},{id:"bubbleBaby",pr:726,group:"Dream bubbles grow",label:"A baby's bubble",note:"A baby's bubbles, as a share of the witch's.",control:{type:"slider",min:.5,max:2,step:.05},default:.8,apply:{knob:"bubbles.levelScale.0"}},{id:"bubbleAdult",pr:726,group:"Dream bubbles grow",label:"An adult's bubble",note:"An adult's bubbles, as a share of the witch's.",control:{type:"slider",min:.5,max:2.5,step:.05},default:1.3,apply:{knob:"bubbles.levelScale.2"}},{id:"bubbleLegend",pr:726,group:"Dream bubbles grow",label:"A legend's bubble",note:"A legend's bubbles and dreams, as a share of the witch's.",control:{type:"slider",min:.8,max:3,step:.05},default:1.8,apply:{knob:"bubbles.levelScale.3"}}],Me={pr:Oe,group:Ae,decisions:Re},De=748,Fe="Trunk shadows",Be=[{id:"trunkShadowStrength",pr:748,group:"Trunk shadows",label:"Shadow darkness",note:"How dark a trunk's or palm's shadow is at its darkest (near its foot and the light).",control:{type:"slider",min:0,max:1,step:.05},default:.75,apply:{knob:"shadows.trunks.strength"}},{id:"trunkShadowLength",pr:748,group:"Trunk shadows",label:"Shadow length (times the trunk)",note:"The longest a shadow stretches, times its trunk's height.",control:{type:"slider",min:.3,max:3,step:.1},default:2.5,apply:{knob:"shadows.trunks.long"}},{id:"trunkShadowGlowReach",pr:748,group:"Trunk shadows",label:"Her glow's reach (m)",note:"How far from her a trunk still casts a shadow from her glow (fading to nothing at the edge).",control:{type:"slider",min:5,max:80,step:1},default:50,apply:{knob:"shadows.trunks.glowReach"}},{id:"trunkShadowGlowHeight",pr:748,group:"Trunk shadows",label:"Her glow's height (m)",note:"How high her glow casts from: lower makes longer shadows.",control:{type:"slider",min:.5,max:10,step:.25},default:1.25,apply:{knob:"shadows.trunks.glowHeight"}},{id:"trunkShadowMode",pr:748,group:"Trunk shadows",label:"Shadow style",note:"Soft (a blurred silhouette, as dark as hard at its core), hard (on the art's pixels, two tones) or off.",control:{type:"choice",options:[{value:"soft",label:"Soft"},{value:"hard",label:"Hard"},{value:"off",label:"Off"}]},default:"soft",apply:{knob:"shadows.trunks.mode"}},{id:"trunkShadowCore",pr:748,group:"Trunk shadows",label:"Soft shadow's core",note:"Soft: how soon it reaches full darkness toward its foot and the light (smaller: a bigger dark core).",control:{type:"slider",min:.05,max:1,step:.05},default:.8,apply:{knob:"shadows.trunks.core"}},{id:"trunkShadowAcross",pr:748,group:"Trunk shadows",label:"Width that casts",note:"The share of a trunk's sprite width that casts (smaller: just the trunk; larger: its low boughs too).",control:{type:"slider",min:.2,max:1,step:.05},default:1,apply:{knob:"shadows.trunks.across"}},{id:"trunkShadowFireReach",pr:748,group:"Trunk shadows",label:"A campfire's reach (m)",note:"How far a campfire's light, and so its shadows, reach (it lights the ground that far too).",control:{type:"slider",min:8,max:60,step:1},default:40,apply:{knob:"lights.campfire.reach"}}],ze={pr:De,group:Fe,decisions:Be},Ie=751,Pe="Chart moon",Ge=[{id:"chartMoonShadow",pr:751,group:"Chart moon",label:"Island shadow darkness",note:"How dark the islands' moon shadows are on the sea and in their valleys (0 none).",control:{type:"slider",min:0,max:1,step:.05},default:.6,apply:{knob:"chart.moon.shadow"}},{id:"chartMoonHeight",pr:751,group:"Chart moon",label:"Moon height (degrees)",note:"How high the moon goes; lower makes the shadows longer.",control:{type:"slider",min:6,max:60,step:1},default:22,apply:{knob:"chart.moon.height"}},{id:"chartMoonTurn",pr:751,group:"Chart moon",label:"Seconds a turn",note:"How long the moon takes to go once round the chart.",control:{type:"slider",min:30,max:600,step:10},default:240,apply:{knob:"chart.moon.turn"}},{id:"chartMoonRise",pr:751,group:"Chart moon",label:"Rise (s)",note:"How long the moon takes to rise over the north-west edge as the chart opens.",control:{type:"slider",min:0,max:15,step:.5},default:6,apply:{knob:"chart.moon.rise"}},{id:"chartMoonDisc",pr:751,group:"Chart moon",label:"Moon disc in the sky",note:"Draw the moon itself past the rim, where it is.",control:{type:"toggle"},default:!0,apply:{knob:"chart.moon.disc"}},{id:"chartEdgeBand",pr:751,group:"Chart moon",label:"Empty sea round the edge",note:"How far the open sea reaches past the furthest islands, as a share of their radius.",control:{type:"slider",min:0,max:.6,step:.02},default:.18,apply:{knob:"chart.edgeBand"}}],Ne={pr:Ie,group:Pe,decisions:Ge},qe=752,We="Sigil glow",Ve=[{id:"sigilGlyph",pr:752,group:"Sigil glow",label:"Sigil strength",note:"How bright every sigil is drawn (placed, runes, ghost, stack, treetops). 0.5 stays under the bloom; lift it if they're faint on bright ground.",control:{type:"slider",min:0,max:1.5,step:.05},default:.5,apply:{knob:"leash.sigilGlyph"}},{id:"sigilHalo",pr:752,group:"Sigil glow",label:"Sigil halo",note:"The soft glow under placed sigils, ready runes and relic sigils, times its old strength (0: none).",control:{type:"slider",min:0,max:1,step:.05},default:0,apply:{knob:"leash.sigilHalo"}}],Je={pr:qe,group:We,decisions:Ve},Ue=754,Ke="Trunk shadow fades",Qe=[{id:"trunkShadowFoot",pr:754,group:"Trunk shadow fades",label:"Fade at the foot (m)",note:"How far from its trunk's foot a shadow fades in from nothing (0: none).",control:{type:"slider",min:0,max:6,step:.25},default:1.5,apply:{knob:"shadows.trunks.foot"}},{id:"trunkShadowTaper",pr:754,group:"Trunk shadow fades",label:"Taper at the foot (m)",note:"How far from its foot a shadow opens out from a third of its width, so wide roots don't splay (0: none).",control:{type:"slider",min:0,max:6,step:.25},default:2,apply:{knob:"shadows.trunks.taper"}},{id:"trunkShadowNear",pr:754,group:"Trunk shadow fades",label:"Fade near her (m)",note:"A trunk's shadow fades to nothing as she comes within this distance of the trunk (0: never).",control:{type:"slider",min:0,max:20,step:.5},default:6,apply:{knob:"shadows.trunks.near"}},{id:"trunkShadowCover",pr:754,group:"Trunk shadow fades",label:"Darkens grass and flowers",note:"How much a shadow darkens the grass, flowers and tufts it falls on (1: as much as the ground; 0: not at all).",control:{type:"slider",min:0,max:1,step:.05},default:1,apply:{knob:"shadows.trunks.cover"}}],Ye={pr:Ue,group:Ke,decisions:Qe},Xe=755,Ze="Sound voice budget",eo=[{id:"sfxVoices",pr:755,group:"Sound voice budget",label:"Most sound effects at once",note:"The one-shot sound effects allowed at once; past it, the ones that matter least (far creatures, the beds' little details) aren't played and lesser ones playing are cut short for hers and the stings. 0: no limit. Lower it if the sound cuts out.",control:{type:"slider",min:0,max:64,step:1},default:24,apply:{knob:"sfx.budget.voices"}}],oo={pr:Xe,group:Ze,decisions:eo},to=756,so="Sigil backing",ao=[{id:"sigilBackingDark",pr:756,group:"Sigil backing",label:"Backing darkness",note:"How dark the patch under every sigil on the ground is (0: none, and no opaque sigil either: as #752).",control:{type:"slider",min:0,max:1,step:.05},default:.85,apply:{knob:"leash.sigilBacking.dark"}},{id:"sigilBackingSize",pr:756,group:"Sigil backing",label:"Backing size (times the sigil)",note:"How wide the dark patch is, times the sigil's own width.",control:{type:"slider",min:.8,max:2,step:.05},default:1.1,apply:{knob:"leash.sigilBacking.size"}},{id:"sigilBackingInk",pr:756,group:"Sigil backing",label:"Sigil opacity",note:"How solid the sigil is painted over its patch, times how much it shows (a fresh rune, the ghost fainter).",control:{type:"slider",min:0,max:3,step:.1},default:1.5,apply:{knob:"leash.sigilBacking.ink"}}],no={pr:to,group:so,decisions:ao},ro=759,io="Scenery shadows",lo=[{id:"sceneryShadows",pr:759,group:"Scenery shadows",label:"Scenery casts shadows",note:"Temples, castles, ruins, set pieces, relics, runestones and soundsystems cast shadows from her glow and the campfires, as the tree trunks do.",control:{type:"toggle"},default:!0,apply:{knob:"shadows.trunks.scenery"}},{id:"sceneryShadowMin",pr:759,group:"Scenery shadows",label:"Shortest that casts (m)",note:"Scenery shorter than this casts no shadow.",control:{type:"slider",min:0,max:6,step:.1},default:1.2,apply:{knob:"shadows.trunks.sceneryMin"}},{id:"shadowGlowLight",pr:759,group:"Scenery shadows",label:"Glowing casters' shadows",note:"How light the shadows of things lit with their own colour are (runestones, soundsystems), in a soft shade of that colour (0: as dark as any).",control:{type:"slider",min:0,max:1,step:.05},default:.7,apply:{knob:"shadows.trunks.glowLight"}},{id:"sceneryShadowFoot",pr:759,group:"Scenery shadows",label:"Fade at the base (m)",note:"Scenery's shadows (runestones, soundsystems, ruins...) fade in from nothing at their base, over this far past their own edge (0: no fade).",control:{type:"slider",min:0,max:8,step:.25},default:2,apply:{knob:"shadows.trunks.sceneryFoot"}},{id:"sceneryShadowTaper",pr:759,group:"Scenery shadows",label:"Taper (times its width)",note:"Scenery's shadows are pinched at their base and open out over this share of the piece's width past its edge, so wide ruins and soundsystems open out over more ground than narrow runestones (0: no taper).",control:{type:"slider",min:0,max:2,step:.05},default:.5,apply:{knob:"shadows.trunks.sceneryTaper"}}],po={pr:ro,group:io,decisions:lo},ho=763,co="Soundsystem light",uo=[{id:"lightKnee",pr:763,group:"Soundsystem light",label:"Light knee",note:"How bright the light on a pixel gets before it's eased off (every light summed: the party's, campfires, her glow, the moon). Lower: bright spots tamer.",control:{type:"slider",min:.4,max:2,step:.05},default:.9,apply:{knob:"lights.knee"}},{id:"lightCeiling",pr:763,group:"Soundsystem light",label:"Light ceiling",note:"The most light a pixel ever gets, eased toward from the knee (at or under the knee: no easing, the old blow-out).",control:{type:"slider",min:.4,max:3,step:.05},default:1.1,apply:{knob:"lights.ceiling"}},{id:"partyLight",pr:763,group:"Soundsystem light",label:"Soundsystem light",note:"A partying soundsystem's own light, pulsing with the beat.",control:{type:"slider",min:0,max:3,step:.05},default:1.6,apply:{knob:"party.lightStrength"}},{id:"bloomThreshold",pr:763,group:"Soundsystem light",label:"Bloom threshold",note:"How bright a pixel must be to bloom (everywhere: neons, sigils, lit ground). Higher: less haze over bright ground.",control:{type:"slider",min:.3,max:1.2,step:.05},default:.55,apply:{knob:"bloom.threshold"}}],go={pr:ho,group:co,decisions:uo},mo=770,fo="Chase",bo=[{id:"chaseBand",pr:770,group:"Chase",label:"Chase past the edge",note:"How far past their area's edge wild animals follow her once they're after her (her 💌 provoked them, or the warning ran out with her inside). Ed: chase outside, relatively far.",control:{type:"slider",min:10,max:120,step:5},default:30,apply:{knob:"combat.leaveArea"}},{id:"provoked",pr:770,group:"Chase",label:"Provoked for",note:"Seconds a 💌 landing on a wild animal provokes it to come out after her across its edge (sniping from just outside). 0: never.",control:{type:"slider",min:0,max:15,step:1},default:6,apply:{knob:"wildWatch.provoked"}}],yo={pr:mo,group:fo,decisions:bo},wo=771,ko="Beach pixels",vo=[{id:"sandGrain",pr:771,group:"Beach pixels",label:"Sand grain",note:"How far each of the sand's chunky pixels is lightened or darkened at random (0: flat sand).",control:{type:"slider",min:0,max:.4,step:.02},default:.14,apply:{knob:"beach.grain"}}],_o={pr:wo,group:ko,decisions:vo},xo=806,$o="Debug knobs",So=[{id:"fightScale",pr:806,group:"Debug knobs",label:"Fight scale ([ ])",note:"Every length in a fight times this: attack ranges, lunges, knockback, the packs' patterns, pursuit and aggro (this run's; [ and ] step it). Moved from the debug overlay's panel (Ed, 2026-10-13).",control:{type:"slider",min:.25,max:3,step:.05},default:1,apply:{param:"fightScale"}},{id:"fightSpeed",pr:806,group:"Debug knobs",label:"Fight speed (; ')",note:"Every speed in a fight times this: running, charging, lunging, shots (this run's; ; and ' step it).",control:{type:"slider",min:.25,max:3,step:.05},default:1,apply:{param:"fightSpeed"}},{id:"fightMomentum",pr:806,group:"Debug knobs",label:"Fight momentum (, .)",note:"How heavily creatures in a fight change speed and turn (2: twice as heavy; this run's; , and . step it).",control:{type:"slider",min:.25,max:3,step:.05},default:1,apply:{param:"fightMomentum"}},{id:"treetopSpeed",pr:806,group:"Debug knobs",label:"Treetop speed (m/s)",note:"How fast she flies over the treetops, live.",control:{type:"slider",min:16,max:160,step:2},default:48,apply:{param:"treetopSpeed"}},{id:"areaSize",pr:806,group:"Debug knobs",label:"Area size (m)",note:"How wide each area is: a new map, so it reloads (the old panel's reset; double-click for the built size).",control:{type:"slider",min:56,max:560,step:8},default:168,apply:{param:"areaSize",reload:!0}}],To={pr:xo,group:$o,decisions:So},Ho=857,Co="Coloured shadows",Lo=[{id:"shadowTint",pr:857,group:"Coloured shadows",label:"Shadow colour",note:"How far every shadow (scenery's, the trees' and palms', and the blobs under creatures, the witch and small things) takes the complement of the light it lies in (0: black; a campfire's orange throws blue-violet, moonlight a warm shade).",control:{type:"slider",min:0,max:1,step:.05},default:1,apply:{knob:"shadows.tint"}},{id:"shadowCast",pr:857,group:"Coloured shadows",label:"Shadows darken what stands in them",note:"Creatures, the witch, bushes, props and scenery standing in a trunk's, a palm's or scenery's shadow are darkened and tinted by it where it falls on them (off: only the ground and grass).",control:{type:"toggle"},default:!0,apply:{knob:"shadows.cast"}}],jo={pr:Ho,group:Co,decisions:Lo},Eo=889,Oo="Area edges",Ao=[{id:"areaEdges",pr:889,group:"Area edges",label:"Area edges",note:"The glowing dotted line of sparks round the edge of the party's areas: off by default (Ed, 2026-10-13); on to compare. Off, it isn't drawn or worked out at all.",control:{type:"toggle"},default:!1,apply:{knob:"borders.on"}}],Ro={pr:Eo,group:Oo,decisions:Ao},Mo=906,Do="Canopy cut-away",Fo=[{id:"cutRadius",pr:906,group:"Canopy cut-away",label:"Cut-away size",note:`How big the circle cut in the canopy round her on the ground is, as a share of the screen's width (Ed, 2026-10-14: "the canopy cut-away radius is too large": 0.8, then 0.53, then 0.4). Her light's reach is set from it (glowToCutout), so it grows and shrinks with it; at 0.4 her light reaches as far as it always has.`,control:{type:"slider",min:.2,max:1.2,step:.01},default:.4,apply:{knob:"canopyCutout.screenFraction"}}],Bo={pr:Mo,group:Do,decisions:Fo},zo=911,Io="Low mist",Po=[{id:"mistGain",pr:911,group:"Low mist",label:"Low mist strength",note:`The low drifting mist, times this (mist.gain; 1 as ever). Each area's mood sets its own mist (0.15 at home to 0.34 in the bogs: light.spooky.mist and its areas), and this scales them all (Ed, 2026-10-14: "almost impossible to see").`,control:{type:"slider",min:0,max:5,step:.05},default:1,apply:{knob:"mist.gain"}}],Go={pr:zo,group:Io,decisions:Po},No=916,qo="Flying cooldown",Wo=[{id:"riseCooldown",pr:916,group:"Flying cooldown",label:"Flying cooldown (s)",note:"Seconds after she lands before she can rise to the treetops again (riseCooldown; 3 as shipped in #649: players rose instead of dodging). The plain broom halves it (spells.plain.riseCooldown). 0 lets her rise at once.",control:{type:"slider",min:0,max:10,step:.25},default:3,apply:{knob:"riseCooldown"}}],Vo={pr:No,group:qo,decisions:Wo},Jo=922,Uo="Treehouse",Ko=[{id:"houseCameraAngle",pr:922,group:"Treehouse",label:"Indoor camera angle",note:`Landed on the treehouse's floor the camera eases to this angle, degrees below the horizon (camera.house.angle; Ed, 2026-10-14: "the camera zooms in so you can see the detail").`,control:{type:"slider",min:10,max:45,step:1},default:24,apply:{knob:"camera.house.angle"}},{id:"houseCameraDistance",pr:922,group:"Treehouse",label:"Indoor camera distance",note:"Indoors the camera's distance is the ordinary one times this (camera.house.distance): smaller is closer.",control:{type:"slider",min:.3,max:1,step:.02},default:.62,apply:{knob:"camera.house.distance"}},{id:"houseCameraEase",pr:922,group:"Treehouse",label:"Indoor camera ease",note:"Seconds the camera takes to push in as she lands on the balcony, and back out as she flies off (camera.house.ease).",control:{type:"slider",min:.2,max:3,step:.1},default:1,apply:{knob:"camera.house.ease"}},{id:"houseLandTime",pr:922,group:"Treehouse",label:"Landing on the balcony",note:"Seconds she takes to come down onto the balcony when she flies onto it at treetop height (treehouse.house.landTime).",control:{type:"slider",min:.1,max:1.2,step:.05},default:.35,apply:{knob:"treehouse.house.landTime"}},{id:"houseRise",pr:922,group:"Treehouse",label:"Rising from the circle",note:"After a knockout, seconds she takes to rise out of the magic circle's floor before walking to her decks (knockout.rise).",control:{type:"slider",min:0,max:3,step:.1},default:.9,apply:{knob:"knockout.rise"}},{id:"houseFall",pr:922,group:"Treehouse",label:"Fall off the balcony",note:"With this on she has no broom: off the balcony's open rim she falls and comes back at the circle (treehouse.house.fall.on). Off, she flies again. A switch until the brooms are objects (step 3).",control:{type:"toggle"},default:!1,apply:{knob:"treehouse.house.fall.on"}}],Qo={pr:Jo,group:Uo,decisions:Ko},Yo=923,Xo="Bounce-off",Zo=[{id:"refusedVolume",pr:923,group:"Bounce-off",label:"Refusal whine volume",note:"How loud an enraged animal's whine is when it refuses a 💌 (sfx.refused.volume; 0.4 as shipped: about the enraged growl's level). 0 is silent.",control:{type:"slider",min:0,max:1,step:.05},default:.4,apply:{knob:"sfx.refused.volume"}}],et={pr:Yo,group:Xo,decisions:Zo},ot=927,tt="Volume",st=!0,at=[{id:"musicVolume",pr:927,group:"Volume",label:"Music",note:`The music's volume (music.volume; 0.5 as built). Remembered on this browser (Ed, 2026-10-14: "being able to control music and sfx volume separately").`,control:{type:"slider",min:0,max:1,step:.05},default:.5,persist:!0,apply:{knob:"music.volume"}},{id:"sfxVolume",pr:927,group:"Volume",label:"Sound effects",note:"The sound effects' volume (sfx.volume; 1 as built): the 💌s, the animals' voices, the ambience, her decks. Remembered on this browser.",control:{type:"slider",min:0,max:1,step:.05},default:1,persist:!0,apply:{knob:"sfx.volume"}}],nt={pr:ot,group:tt,pinned:st,decisions:at},rt=936,it="Leash arc",lt=[{id:"threadArcSlack",pr:936,group:"Leash arc",label:"Leash bow (m per m)",note:`How high a strained leash's thread bows upward, in metres per metre of its length while slack (it flattens as the leash goes taut). 0.4 as shipped; 0.8 now (Ed, 2026-10-15: "The arc of leashes should be higher").`,control:{type:"slider",min:0,max:1.5,step:.05},default:.8,apply:{knob:"bond.threadArcSlack"}},{id:"threadArcMax",pr:936,group:"Leash arc",label:"Leash bow cap (m)",note:"The most a leash's thread bows, in metres, whatever its length. 4 as shipped; 8 now.",control:{type:"slider",min:0,max:15,step:.5},default:8,apply:{knob:"bond.threadArcMax"}}],dt={pr:rt,group:it,decisions:lt},pt=937,ht="Stack sigils",ct=[{id:"stackOver",pr:937,group:"Stack sigils",label:"Stack over the scenery",note:'The sigils stacked above her head drawn over everything (no depth test, after the see-through pass), so no trunk or crown hides them (Ed, 2026-10-15: "never obscured by scenery"). Off: hidden behind scenery as before.',control:{type:"toggle"},default:!0,apply:{knob:"stack.over"}},{id:"stackBright",pr:937,group:"Stack sigils",label:"Stack brightness",note:`How bright each stacked sigil is drawn, times the ground sigils' (leash.sigilGlyph). 1 as before; 1.6 now (Ed: "more opacity"). Past about 1.1 the glyph starts to bloom.`,control:{type:"slider",min:.5,max:3,step:.1},default:1.6,apply:{knob:"stack.bright"}},{id:"stackBacking",pr:937,group:"Stack sigils",label:"Stack backing disc",note:"A near-black disc behind each stacked sigil, this opaque (0 none, 1 solid), so the glyph reads against lit crowns and the sky.",control:{type:"slider",min:0,max:1,step:.05},default:.6,apply:{knob:"stack.backing"}},{id:"stackBackSize",pr:937,group:"Stack sigils",label:"Backing disc size",note:"The backing disc's width, times the sigil's.",control:{type:"slider",min:1,max:2,step:.05},default:1.3,apply:{knob:"stack.backSize"}}],ut={pr:pt,group:ht,decisions:ct},gt=938,mt="Sigil runs",ft=[{id:"sigilRuns",pr:938,group:"Sigil runs",label:"Sigil runs",note:"Hold the sigil button (E, the pad's square, touch) on after a press that picked a sigil up and she keeps picking up every sigil she runs over; hold it after a press that put one down and each empty hex she walks into takes the next (Ed, 2026-10-15). Off: a press does one thing, holding does nothing more (holding E with nothing to do still puts her hat down either way).",control:{type:"toggle"},default:!0,apply:{knob:"leash.runs"}}],bt={pr:gt,group:mt,decisions:ft},yt=940,wt="One cooldown",kt=[{id:"cooldownShared",pr:940,group:"One cooldown",label:"Dodge and take-off share one cooldown",note:`On, her dodge and her take-off share one counter (Ed, 2026-10-15: "One trail, one cooldown"): a dodge adds the dodge cooldown, a take-off the take-off amount, a landing the flying cooldown (#916), each going only when the counter has room for it; her trail is as long as the counter is full. Off: the dodge's charges and the flying cooldown run apart as before.`,control:{type:"toggle"},default:!0,apply:{knob:"cooldown.shared"}},{id:"cooldownRise",pr:940,group:"One cooldown",label:"Take-off adds (s)",note:"Seconds a take-off adds to the shared counter (2 now; the plain broom halves it). Over the counter's room, a take-off needs it empty.",control:{type:"slider",min:0,max:6,step:.25},default:2,apply:{knob:"cooldown.rise"}},{id:"dashCooldown",pr:940,group:"One cooldown",label:"Dodge adds (s)",note:"Seconds a dodge adds to the shared counter (1 as shipped; shared off, the seconds before the next blink comes back).",control:{type:"slider",min:.25,max:4,step:.25},default:1,apply:{knob:"dash.cooldown"}},{id:"dashCharges",pr:940,group:"One cooldown",label:"Dodges in a row",note:"How many dodges the counter has room for (2 as shipped, Ed 2026-10-08: its room is this times the dodge's seconds; shared off, her blinks before the cooldown). The flying cooldown (#916) adds more than the room, so after landing both wait.",control:{type:"slider",min:1,max:4,step:1},default:2,apply:{knob:"dash.charges"}},{id:"trailCooldown",pr:940,group:"One cooldown",label:"Trail per full cooldown (m)",note:"Her trail is at least this many metres times the counter's share in use (full right after a take-off or a landing, half after a dodge with two in hand), draining with it. 0: the trail shows only her speed, as before.",control:{type:"slider",min:0,max:60,step:1},default:24,apply:{knob:"trail.cooldown"}},{id:"trailBySpeed",pr:940,group:"One cooldown",label:"Trail by speed too",note:"On, her speed still gives the trail its length as before (5 m at full speed on the ground, 20 m over the treetops), the cooldown's length over it. Off, the trail shows the cooldown alone.",control:{type:"toggle"},default:!0,apply:{knob:"trail.bySpeed"}}],v